FROM t_plan
WHERE is_deleted = 0

    AND plan_type = #{query.planType}


    AND title LIKE CONCAT('%', #{query.title}, '%')


    AND dept_id = #{query.deptId}



        AND (plan_type = 1 OR employee_id = #{query.employeeId})


        AND employee_id = #{query.employeeId}



    AND status = #{query.status}

mapper.select:
SELECT


ORDER BY priority DESC, end_date ASC, id DESC
LIMIT #{offset}, #{size}
